using namespace std;

bool isSubsequenceHelper(const string& s, const string& t, int i, int j) {
    if (i == (int)s.size()) return true;                            // every character of s has already been matched
    if (j == (int)t.size()) return false;                             // ran out of t before matching all of s
    if (s[i] == t[j]) {
        return isSubsequenceHelper(s, t, i + 1, j + 1);                    // matched, advance both
    }
    return isSubsequenceHelper(s, t, i, j + 1);                             // no match here, only advance through t
}

bool isSubsequence(string s, string t) {
    return isSubsequenceHelper(s, t, 0, 0);
}

int main() {
    string s = "abc";
    string t = "ahbgdc";
    cout << (isSubsequence(s, t) ? "true" : "false") << endl;
    return 0;
}

