import java.util.*;

public class Main {
    Map<Character, List<Integer>> buildIndex(String t) {
        Map<Character, List<Integer>> positions = new HashMap<>();
        for (int idx = 0; idx < t.length(); idx++) {
            positions.computeIfAbsent(t.charAt(idx), k -> new ArrayList<>()).add(idx); // every index for this letter
        }
        return positions;
    }

    boolean isSubsequenceQuery(String s, Map<Character, List<Integer>> positions) {
        int lastMatch = -1;
        for (char ch : s.toCharArray()) {
            List<Integer> candidates = positions.getOrDefault(ch, Collections.emptyList());
            int idx = upperBound(candidates, lastMatch);                    // first position strictly after the last match
            if (idx == candidates.size()) return false;
            lastMatch = candidates.get(idx);
        }
        return true;
    }

    int upperBound(List<Integer> list, int value) {
        int lo = 0, hi = list.size();
        while (lo < hi) {
            int mid = (lo + hi) / 2;
            if (list.get(mid) <= value) lo = mid + 1; else hi = mid;
        }
        return lo;
    }

    public static void main(String[] args) {
        String t = "ahbgdc";
        String s = "abc";
        Main solution = new Main();
        Map<Character, List<Integer>> index = solution.buildIndex(t);
        System.out.println(solution.isSubsequenceQuery(s, index));
    }
}

