#include <bits/stdc++.h>
using namespace std;

unordered_map<char, vector<int>> buildIndex(const string& t) {
    unordered_map<char, vector<int>> positions;
    for (int idx = 0; idx < (int)t.size(); idx++) {
        positions[t[idx]].push_back(idx);                                // every index where this letter appears in t
    }
    return positions;
}

bool isSubsequenceQuery(const string& s, unordered_map<char, vector<int>>& positions) {
    int lastMatch = -1;
    for (char ch : s) {
        auto& candidates = positions[ch];
        auto it = upper_bound(candidates.begin(), candidates.end(), lastMatch); // first position after the last match
        if (it == candidates.end()) return false;
        lastMatch = *it;
    }
    return true;
}

int main() {
    string t = "ahbgdc";
    string s = "abc";
    auto index = buildIndex(t);
    cout << (isSubsequenceQuery(s, index) ? "true" : "false") << endl;
    return 0;
}
